def _orientations(cells):
    variants = set()
    for reflect in (False, True):
        for turns in range(4):
            pts = []
            for r, c in cells:
                if reflect:
                    c = -c
                for _ in range(turns):
                    r, c = c, -r
                pts.append((r, c))
            mr = min(r for r, _ in pts)
            mc = min(c for _, c in pts)
            variants.add(tuple(sorted((r-mr, c-mc) for r, c in pts)))
    return variants


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 2, 8)}
    # The non-background color is the small template embedded in the noise.
    if not colors:
        return [row[:] for row in grid]
    color = min(colors)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    base_r = min(r for r, _ in cells)
    base_c = min(c for _, c in cells)
    shape = [(r-base_r, c-base_c) for r, c in cells]
    out = [row[:] for row in grid]
    pattern = tuple(sorted(shape))
    ph = max(r for r, _ in pattern) + 1
    pw = max(c for _, c in pattern) + 1
    for r0 in range(h-ph+1):
        for c0 in range(w-pw+1):
            if all(grid[r0+r][c0+c] == 0 for r, c in pattern):
                for r, c in pattern:
                    out[r0+r][c0+c] = color
    return out

